// direct encryption is impossible here so we need help from mongoose hooks 
// eg- a (pre) hook which is a middleware what this does is when our data is going to be saved just before it like we want 
// to encrypt our password we can do it using this hook 


import mongoose, {Schema} from "mongoose";
// here we have direclty imported Schema from the mongoose so we use Schema rather than mongoose.Schema
import jwt from "jsonwebtoken"
import bcrypt from "bcrypt"

const userSchema = new Schema({

    username: {
        type: String,
        required: true,
        unique: true,
        lowercase: true,
        trim: true,
        index: true
        // index true we do for those which are searcable items like username will be one of the most searchable thing
    },

    email: {
        type: String,
        required: true,
        unique: true,
        lowercase: true,
        trim: true
    },

    fullName: {
        type: String,
        required: true,
        trim: true,
        index: true
    },

    avatar: {
        type: String, // using cloudinary services ie its url 
        required: true,
    },

    coverImage: {
        type: String, // using cloudinary services ie its url
    },

    password: { // one of the important challanges
        type: String,
        required: [true, "Password is required"]
    },

    watchHistory: [// array of video 
        {
            type: Schema.Types.ObjectId,
            ref: "Video"
        }
    ],
    refreshToken: {
        type: String
    }

}, {timestamps: true})


// here save is for whenever we are saving data just vefore it run this middleware 
// we dont use arrow function here as arrow function dont use this feature and we want a particula user who is saving 
// his or her data so for that we write a mannual function there 
