// so to only make this method run when we chage password we do 

userSchema.pre("save", async function(next) 
{
    if(this.isModified("password"))
    {
        this.password = bcrypt.hash(this.password, 12);
        next();
        // this next is for so that we can now go to next middleware or go next bcz with this middleware our work is done 
    }
    
})

// as mongoose give us in build methods and give us freedom to make our own methods we can make a method to check weather a 
// user is a vaild user or not by checking its password as we know we have encrypted tthe password so 
// in that method we are gonna decrypt the password and check with the user's password the user has given 
// currently 

// this is how to make a custom method
userSchema.methods.isPasswordCorrect = async function(password)// the password user has given rn
{
    // this too takes time so we use await bcz this is cryptography which takes time 
    return await bcrypt.compare(password, this.password);
    // this bcrypt library has its own in it to check password so this is how we do it 
    // first thing we pass is the current ppassword given by the user 2nd thing is the encrypted password
    // this library compare both and than return a boolean value 
}

// we can also make a access token generate method too here 

userSchema.methods.generateAccessTokent = async function()
{
    return await jwt.sign( // here this jwt.sign return access token when it is ready here 
        {
            _id: this._id,
            email: this.email,
            username: this.username,
            fullName: this.fullName
            // this first fullname is the name of the payload key and the second this.fullName is what coming from the database
            // so this.fullName in this "fullName" must match with "fullName" which is stored in the db we cant use "fullname"
        },
        // another thigit wants is the access token secret 
        process.env.ACCESS_TOKEN_SECRET,
        {
            expiresIn: process.env.ACCESS_TOKEN_EXPIRY
            // this is when our token will be expired
        },
    )
    // jwt has a sign method which generate token we also give sign a payload which can be string or an object 
}
// and just like our access token our refresh token is also generated like this 
userSchema.methods.generateRefreshToken = async function()
{
    return await jwt.sign( // here this jwt.sign return refresh token when it is ready here 
        {
            _id: this._id
            // this refresh token has less info as it gets refreshed time to time so we dont store that much data in it 
        },
        process.env.REFRESH_TOKEN_SECRET,
        {
            expiresIn: process.env.REFRESH_TOKEN_EXPIRY
        },
    )
}

export const User = mongoose.model("User", userSchema);












































